median_value <- function(values) {
  ordered <- sort(values)
  n <- length(ordered)
  if (n %% 2L) ordered[(n+1L) %/% 2L] else (ordered[n %/% 2L]+ordered[n %/% 2L+1L])/2
}
prepare_record <- function(record,minimum_run) {
  values <- record$values
  numeric <- sort(as.integer(names(values)[!is.na(values)]))
  first <- numeric[1L]
  last <- tail(numeric,1L)
  reasons <- setNames(rep("",last-first+1L),as.character(first:last))
  for (t in first:last) {
    key <- as.character(t)
    if (!(key %in% names(values))) reasons[key] <- "absent" else if (is.na(values[[key]])) reasons[key] <- "na"
  }
  runs <- list()
  cursor <- 1L
  while (cursor <= length(numeric)) {
    start <- stop <- numeric[cursor]
    while (cursor < length(numeric) && numeric[cursor+1L] == stop+1L && values[[as.character(numeric[cursor+1L])]] == values[[as.character(start)]]) {
      cursor <- cursor+1L
      stop <- numeric[cursor]
    }
    if (stop-start+1L >= minimum_run) {
      runs[[length(runs)+1L]] <- list(start=start,stop=stop,value=values[[as.character(start)]])
      reasons[as.character(seq.int(start+1L,stop))] <- "flat"
    }
    cursor <- cursor+1L
  }
  list(
      first=first,
      last=last,
      record_length=last-first,
      numeric_times=numeric,
      reasons=reasons,
      flat_runs=runs,
      candidates=numeric[reasons[as.character(numeric)] == ""],
      values=values,
      rows=record$rows
  )
}
list_gaps <- function(cleaning) {
  gaps <- list()
  start <- cleaning$first
  while (start <= cleaning$last) {
    if (cleaning$reasons[[as.character(start)]] == "") {
      start <- start+1L
      next
    }
    stop <- start
    while (stop < cleaning$last && cleaning$reasons[[as.character(stop+1L)]] != "") stop <- stop+1L
    causes <- unique(cleaning$reasons[as.character(start:stop)])
    gaps[[length(gaps)+1L]] <- list(
        start=start,
        stop=stop,
        cause=if (length(causes) == 1L) causes[[1L]] else "mixed"
    )
    start <- stop+1L
  }
  gaps
}
detect_spikes <- function(cleaning,residuals,settings) {
  tested <- 0L
  spikes <- list()
  for (t in cleaning$candidates) {
    key <- as.character(t)
    neighbors <- residuals[as.character(cleaning$candidates[abs(cleaning$candidates-t) <= settings$spike_window])]
    if (length(neighbors) < settings$spike_minimum) next
    tested <- tested+1L
    center <- median_value(neighbors)
    mad <- median_value(abs(neighbors-center))
    limit <- max(settings$spike_factor*1.4826*mad,settings$spike_floor)
    if (abs(residuals[[key]]-center) > limit) {
      cleaning$reasons[key] <- "spike"
      spikes[[length(spikes)+1L]] <- list(
          time=t,
          value=cleaning$values[[key]],
          residual=residuals[[key]],
          median=center,
          mad=mad,
          limit=limit
      )
    }
  }
  cleaning$tested <- tested
  cleaning$spikes <- spikes
  cleaning$usable <- cleaning$candidates[cleaning$reasons[as.character(cleaning$candidates)] == ""]
  cleaning$gaps <- list_gaps(cleaning)
  cleaning
}

TIDE_PI <- 3.141592653589793
angle <- function(speed,time) {
  degrees <- speed*time
  reduced <- degrees-360*floor(degrees/360)
  reduced*TIDE_PI/180
}
regressors <- function(time,selected) {
  vector <- 1
  for (constituent in selected) {
    theta <- tide_angle(constituent$speed,time)
    vector <- c(vector,cos(theta),sin(theta))
  }
  vector
}
solve_with_inverse <- function(matrix,right) {
  n <- length(right)
  augmented <- cbind(matrix,right,diag(1,n))
  for (column in seq_len(n)) {
    pivot <- column-1L+which.max(abs(augmented[seq.int(column,n),column]))
    if (pivot != column) augmented[c(column,pivot),] <- augmented[c(pivot,column),,drop=FALSE]
    if (column < n) for (row in seq.int(column+1L,n)) {
      factor <- augmented[row,column]/augmented[column,column]
      for (c in seq.int(column,2L*n+1L)) augmented[row,c] <- augmented[row,c]-factor*augmented[column,c]
    }
  }
  solutions <- list()
  for (column in seq.int(n+1L,2L*n+1L)) {
    solution <- numeric(n)
    for (i in seq.int(n,1L)) {
      current <- augmented[i,column]
      if (i < n) for (j in seq.int(i+1L,n)) current <- current-augmented[i,j]*solution[j]
      solution[i] <- current/augmented[i,i]
    }
    solutions[[length(solutions)+1L]] <- solution
  }
  list(coefficients=solutions[[1L]],inverse=do.call(cbind,solutions[-1L]))
}
fit <- function(values,times,selected) {
  n <- 2L*length(selected)+1L
  matrix <- matrix(0,n,n)
  right <- numeric(n)
  for (t in times) {
    vector <- regressors(t,selected)
    observed <- values[[as.character(t)]]
    for (i in seq_len(n)) {
      right[i] <- right[i]+vector[i]*observed
      for (j in seq_len(n)) matrix[i,j] <- matrix[i,j]+vector[i]*vector[j]
    }
  }
  solved <- solve_with_inverse(matrix,right)
  coefficients <- solved$coefficients
  constants <- list()
  for (k in seq_along(selected)) {
    c <- selected[[k]]
    a <- coefficients[2L*k]
    b <- coefficients[2L*k+1L]
    amplitude <- sqrt(a*a+b*b)
    phase <- atan2(b,a)*180/TIDE_PI
    if (phase < 0) phase <- phase+360
    constants[[c$name]] <- list(
        speed=c$speed,
        a=a,
        b=b,
        amplitude=amplitude,
        phase=phase,
        index_a=2L*k,
        index_b=2L*k+1L
    )
  }
  list(
      selected=selected,
      coefficients=coefficients,
      inverse=solved$inverse,
      mean_level=coefficients[1L],
      constants=constants,
      unknowns=n
  )
}

decimal <- function(value,places) {
  text <- sprintf(paste0("%.",places,"f"),value)
  if (startsWith(text,"-") && as.numeric(text) == 0) substring(text,2L) else text
}
optional <- function(value,places) if (is.null(value)) "none" else decimal(value,places)
write_lines <- function(name,lines) {
  dir.create("output",showWarnings=FALSE)
  writeLines(lines,file.path("output",name),useBytes=TRUE)
}
render_plot <- function(grid,labels) {
  width <- max(nchar(labels))
  lines <- vapply(
      seq_len(nrow(grid)),
      function(row) paste0(sprintf(paste0("%",width,"s"),labels[row])," |",paste(grid[row,],collapse=""),"|"),
      character(1)
  )
  axis <- paste(ifelse((0:(ncol(grid)-1L)) %% 6L == 0L,"+","-"),collapse="")
  c(lines,paste0(strrep(" ",width)," +",axis,"+"))
}
